export default function makeController() {
  let targetIndex = -1, phase = 'climb', settle = 0;
  let intX = 0, intY = 0, intZ = 0;
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  return {
    step(obs) {
      const p = obs.pos, v = obs.vel;
      let target;
      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (targetIndex !== obs.gateIndex) { targetIndex = obs.gateIndex; phase = 'align'; settle = 0; }
        if (phase === 'align') {
          target = { x: gate.x - 0.45, y: gate.y, z: gate.z };
          if (Math.hypot(target.x - p.x, target.y - p.y, target.z - p.z) < 0.14 && Math.hypot(v.x, v.y, v.z) < 0.5) settle++;
          else settle = 0;
          if (settle > 8) phase = 'cross';
        }
        if (phase === 'cross') target = { x: gate.x + 0.35, y: gate.y, z: gate.z };
      } else {
        target = { x: obs.pad.centre.x, y: 0.65, z: obs.pad.centre.z };
        if (phase !== 'descend' && Math.hypot(target.x - p.x, target.z - p.z) < 0.12 && Math.hypot(v.x, v.z) < 0.35) phase = 'descend';
        if (phase === 'descend') target.y = 0.02;
      }

      const ex = target.x - p.x;
      const ey = target.y - p.y;
      const ez = target.z - p.z;

      intX = clamp(intX + ex * 0.01, -2.5, 2.5);
      intY = clamp(intY + ey * 0.01, -1.5, 2.5);
      intZ = clamp(intZ + ez * 0.01, -2.5, 2.5);

      const ax = clamp(5.0 * ex - 3.8 * v.x + 3.5 * intX, -5.0, 5.0);
      const az = clamp(5.0 * ez - 3.8 * v.z + 3.5 * intZ, -5.0, 5.0);
      const ay = clamp(6.5 * ey - 4.0 * v.y + 3.0 * intY, -4.5, 5.5);

      const cy = Math.cos(obs.att.yaw), sy = Math.sin(obs.att.yaw);
      const pitch = clamp((cy * ax - sy * az) / 9.81, -0.55, 0.55);
      const roll = clamp(-(sy * ax + cy * az) / 9.81, -0.55, 0.55);
      const thrust = (0.78 * (9.81 + ay)) / (16 * Math.max(0.6, Math.cos(obs.att.roll) * Math.cos(obs.att.pitch)));
      return { thrust, roll, pitch, yawRate: -2 * obs.att.yaw };
    },
  };
}

