export default function makeController() {
  let targetIndex = -1, phase = 'align', settle = 0;
  let distX = 0, distY = -9.81, distZ = 0;
  let lastVel = null, lastAccCmd = { x: 0, y: 0, z: 0 };
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  return {
    step(obs) {
      const p = obs.pos, v = obs.vel, att = obs.att;
      const dt = 0.01;

      // Estimate actual acceleration from velocity change and update disturbance estimate
      if (lastVel && obs.t > 0.05) {
        const realAx = (v.x - lastVel.x) / dt;
        const realAy = (v.y - lastVel.y) / dt;
        const realAz = (v.z - lastVel.z) / dt;

        // Current tilt acceleration contribution (using previous command / current attitude)
        const bodyX = Math.sin(att.pitch) * Math.cos(att.roll);
        const bodyZ = -Math.sin(att.roll);
        const dirX = Math.cos(att.yaw) * bodyX + Math.sin(att.yaw) * bodyZ;
        const dirY = Math.cos(att.pitch) * Math.cos(att.roll);
        const dirZ = -Math.sin(att.yaw) * bodyX + Math.cos(att.yaw) * bodyZ;

        const thrustAcc = lastAccCmd.thrustAcc || 9.81;
        const modelAx = thrustAcc * dirX;
        const modelAy = thrustAcc * dirY - 9.81;
        const modelAz = thrustAcc * dirZ;

        const alpha = 0.12;
        distX += alpha * (realAx - modelAx - distX);
        distY += alpha * (realAy - modelAy - distY);
        distZ += alpha * (realAz - modelAz - distZ);
        distX = clamp(distX, -8, 8);
        distY = clamp(distY, -6, 6);
        distZ = clamp(distZ, -8, 8);
      }
      lastVel = { x: v.x, y: v.y, z: v.z };

      let target, targetVel = { x: 0, y: 0, z: 0 };
      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (targetIndex !== obs.gateIndex) {
          targetIndex = obs.gateIndex;
          phase = 'align';
          settle = 0;
        }
        const dy = Math.abs(p.y - gate.y);
        const dz = Math.abs(p.z - gate.z);
        if (phase === 'align') {
          target = { x: gate.x - 0.35, y: gate.y, z: gate.z };
          if (p.x > gate.x - 0.55 && p.x < gate.x && dy < 0.06 && dz < 0.022 && Math.abs(v.y) < 0.25 && Math.abs(v.z) < 0.18) {
            settle++;
          } else {
            settle = Math.max(0, settle - 1);
          }
          if (settle >= 4) phase = 'cross';
        }
        if (phase === 'cross') {
          // If blown off alignment before crossing the gate plane, abort back to align
          if (p.x < gate.x - 0.08 && (dy > 0.09 || dz > 0.028)) {
            phase = 'align';
            settle = 0;
            target = { x: gate.x - 0.35, y: gate.y, z: gate.z };
          } else {
            target = { x: gate.x + 0.30, y: gate.y, z: gate.z };
            targetVel = { x: 0.8, y: 0, z: 0 };
          }
        }
      } else {
        const pad = obs.pad.centre;
        if (targetIndex !== 3) {
          targetIndex = 3;
          phase = 'approach';
        }
        const horizErr = Math.hypot(pad.x - p.x, pad.z - p.z);
        const horizSpd = Math.hypot(v.x, v.z);
        if (phase === 'approach') {
          target = { x: pad.x, y: 0.45, z: pad.z };
          if (horizErr < 0.12 && horizSpd < 0.35 && p.y < 0.65) {
            phase = 'descend';
          }
        }
        if (phase === 'descend') {
          target = { x: pad.x, y: 0.05, z: pad.z };
          if (p.y <= 0.095 && horizErr < 0.12) {
            target = { x: pad.x, y: 0.0, z: pad.z };
          }
        }
      }

      // PD + disturbance rejection
      const kpX = 6.5, kdX = 4.2;
      const kpZ = 9.0, kdZ = 5.0;
      const kpY = 8.0, kdY = 4.5;

      const ax = clamp(kpX * (target.x - p.x) + kdX * (targetVel.x - v.x) - distX, -5.5, 5.5);
      const az = clamp(kpZ * (target.z - p.z) + kdZ * (targetVel.z - v.z) - distZ, -5.5, 5.5);
      const ay = clamp(kpY * (target.y - p.y) + kdY * (targetVel.y - v.y) - distY, -5.0, 6.0);

      const totalAy = Math.max(1.5, 9.81 + ay);
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const bodyAx = cy * ax - sy * az;
      const bodyAz = sy * ax + cy * az;

      // On the pad and low, keep tilt small to satisfy landingTilt < 0.18
      let maxTilt = 0.55;
      if (obs.gateIndex === 3 && p.y < 0.14) maxTilt = 0.14;

      const pitch = clamp(Math.atan2(bodyAx, totalAy), -maxTilt, maxTilt);
      const roll = clamp(-Math.atan2(bodyAz, totalAy), -maxTilt, maxTilt);

      const cosTilt = Math.max(0.55, Math.cos(att.roll) * Math.cos(att.pitch));
      const reqThrustAcc = totalAy / cosTilt;
      lastAccCmd = { thrustAcc: reqThrustAcc };

      // Base mass ~ 0.78kg, max thrust = 16N -> 16 / 0.78 = 20.5 m/s^2 at thrust=1
      let thrust = clamp(reqThrustAcc / 20.5, 0, 1);
      if (obs.gateIndex === 3 && p.y <= 0.085 && Math.hypot(obs.pad.centre.x - p.x, obs.pad.centre.z - p.z) < 0.11 && Math.abs(v.y) < 0.25) {
        thrust = 0;
      }

      return { thrust, roll, pitch, yawRate: clamp(-2.5 * att.yaw, -2, 2) };
    },
  };
}

