        const modelAx = thrustAcc * dirX;
        const modelAy = thrustAcc * dirY - 9.81;
        const modelAz = thrustAcc * dirZ;

        const alpha = 0.20;
        distX += alpha * (realAx - modelAx - distX);
        distY += alpha * (realAy - modelAy - distY);
        distZ += alpha * (realAz - modelAz - distZ);
        distX = clamp(distX, -9, 9);
        distY = clamp(distY, -6, 6);
        distZ = clamp(distZ, -9, 9);
      }
      lastVel = { x: v.x, y: v.y, z: v.z };

      let target, targetVel = { x: 0, y: 0, z: 0 };
      let kpX = 6.5, kdX = 4.2, kpZ = 10.0, kdZ = 5.2, kpY = 8.5, kdY = 4.5;

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (targetIndex !== obs.gateIndex) {
          targetIndex = obs.gateIndex;
          phase = 'align';
          settle = 0;
          intX *= 0.3; intZ *= 0.3;
        }
        const dy = Math.abs(p.y - gate.y);
        const dz = Math.abs(p.z - gate.z);
        // Predicted dy, dz at gate crossing or 0.12s ahead
        const predZ = p.z + v.z * 0.12;
        const predY = p.y + v.y * 0.12;
        const predDz = Math.abs(predZ - gate.z);
        const predDy = Math.abs(predY - gate.y);

        if (phase === 'align') {
          // If we are far or not aligned in z/y, stay behind gate at x = gate.x - 0.32
          const stagingX = (dy < 0.08 && dz < 0.05) ? gate.x - 0.25 : gate.x - 0.35;
          target = { x: stagingX, y: gate.y, z: gate.z };
          if (p.x > gate.x - 0.50 && p.x < gate.x && dy < 0.05 && dz < 0.018 && predDz < 0.020 && Math.abs(v.y) < 0.22 && Math.abs(v.z) < 0.14) {
