      const bodyAz = sy * ax + cy * az;

      let maxTilt = 0.58;
      if (obs.gateIndex === 3 && p.y < 0.12 && Math.hypot(obs.pad.centre.x - p.x, obs.pad.centre.z - p.z) < 0.13) {
