            targetVel = { x: 1.25, y: 0, z: 0 };
            kpZ = 14.5; kdZ = 6.5;
            kpY = 11.0; kdY = 5.2;
          }
        }
      } else {
        const pad = obs.pad.centre;
        if (targetIndex !== 3) {
          targetIndex = 3;
          phase = 'approach';
          intX *= 0.3; intZ *= 0.3;
        }
        const horizErr = Math.hypot(pad.x - p.x, pad.z - p.z);
        const horizSpd = Math.hypot(v.x, v.z);
        if (phase === 'approach') {
          const approachY = clamp(0.16 + 0.50 * horizErr, 0.16, 0.70);
          target = { x: pad.x, y: approachY, z: pad.z };
          if (horizErr < 0.12 && horizSpd < 0.45 && p.y < 0.32) {
            phase = 'descend';
          }
        }
        if (phase === 'descend') {
          if (horizErr > 0.135) {
            target = { x: pad.x, y: 0.15, z: pad.z };
          } else {
            target = { x: pad.x, y: 0.04, z: pad.z };
            targetVel = { x: 0, y: -0.15, z: 0 };
          }
        }
      }

      const ex = clamp(target.x - p.x, -0.8, 0.8);
      const ey = clamp(target.y - p.y, -0.8, 0.8);
      const ez = clamp(target.z - p.z, -0.8, 0.8);

      if (Math.abs(target.x - p.x) < 0.30) intX = clamp(intX + ex * dt, -0.35, 0.35);
      if (Math.abs(target.y - p.y) < 0.30) intY = clamp(intY + ey * dt, -0.35, 0.35);
      if (Math.abs(target.z - p.z) < 0.30) intZ = clamp(intZ + ez * dt, -0.35, 0.35);

      const ax = clamp(kpX * ex + kdX * (targetVel.x - v.x) + 2.5 * intX - distX, -6.5, 6.5);
      const az = clamp(kpZ * ez + kdZ * (targetVel.z - v.z) + 3.5 * intZ - distZ, -6.5, 6.5);
      const ay = clamp(kpY * ey + kdY * (targetVel.y - v.y) + 2.5 * intY - distY, -5.0, 6.5);

      const totalAy = Math.max(2.0, 9.81 + ay);
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const bodyAx = cy * ax - sy * az;
      const bodyAz = sy * ax + cy * az;

      let maxTilt = obs.t < 0.25 ? 0.35 : 0.55;
      if (obs.gateIndex === 3 && p.y < 0.12 && Math.hypot(obs.pad.centre.x - p.x, obs.pad.centre.z - p.z) < 0.13) {
        maxTilt = 0.15;
      }

      const pitch = clamp(Math.atan2(bodyAx, totalAy), -maxTilt, maxTilt);
      const roll = clamp(-Math.atan2(bodyAz, totalAy), -maxTilt, maxTilt);

      const cosTilt = Math.max(0.55, Math.cos(att.roll) * Math.cos(att.pitch));
      const reqThrustAcc = totalAy / cosTilt;

      let thrust = clamp(reqThrustAcc / 19.5, 0, 0.82);
      if (obs.gateIndex === 3 && p.y <= 0.09 && Math.hypot(obs.pad.centre.x - p.x, obs.pad.centre.z - p.z) < 0.12 && Math.abs(v.y) < 0.35) {
        thrust = 0;
      }
      estThrustAcc += 0.25 * (thrust * 19.5 - estThrustAcc);

      return { thrust, roll, pitch, yawRate: clamp(-2.5 * att.yaw, -2, 2) };
    },
  };
}

