export default function makeController() {
  let targetIndex = -1;
  let distX = 0, distY = 0, distZ = 0;
  let fastZ = 0, fastY = 0;
  let intX = 0, intY = 0, intZ = 0;
  let lastVel = null;
  let estThrustAcc = 9.81;
  let massScale = 1.0;
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

  return {
    step(obs) {
      const p = obs.pos, v = obs.vel, att = obs.att;
      const dt = 0.01;

      const bodyX = Math.sin(att.pitch) * Math.cos(att.roll);
      const bodyZ = -Math.sin(att.roll);
      const dirX = Math.cos(att.yaw) * bodyX + Math.sin(att.yaw) * bodyZ;
      const dirY = Math.cos(att.pitch) * Math.cos(att.roll);
      const dirZ = -Math.sin(att.yaw) * bodyX + Math.cos(att.yaw) * bodyZ;

      if (lastVel && obs.t > 0.06 && p.y > 0.085) {
        const realAx = (v.x - lastVel.x) / dt;
        const realAy = (v.y - lastVel.y) / dt;
        const realAz = (v.z - lastVel.z) / dt;

        const modelAx = estThrustAcc * dirX;
        const modelAy = estThrustAcc * dirY - 9.81;
        const modelAz = estThrustAcc * dirZ;

        // Estimate vertical thrust scaling (mass & weak motor)
        if (estThrustAcc > 5.0 && dirY > 0.75) {
          const impliedScale = (realAy + 9.81 + 0.55 * v.y) / (estThrustAcc * dirY);
          massScale = clamp(massScale + 0.04 * (clamp(impliedScale, 0.55, 1.35) - massScale), 0.65, 1.25);
        }

        const rawDx = realAx - modelAx * massScale;
        const rawDy = realAy - (estThrustAcc * massScale * dirY - 9.81);
        const rawDz = realAz - modelAz * massScale;

        distX = clamp(distX + 0.16 * (rawDx - distX), -9.5, 9.5);
        distY = clamp(distY + 0.16 * (rawDy - distY), -5.0, 5.0);
        distZ = clamp(distZ + 0.18 * (rawDz - distZ), -9.5, 9.5);

        fastZ = clamp(fastZ + 0.42 * (rawDz - fastZ), -10.5, 10.5);
        fastY = clamp(fastY + 0.35 * (rawDy - fastY), -6.0, 6.0);
      }
      lastVel = { x: v.x, y: v.y, z: v.z };

      let target = { x: p.x, y: p.y, z: p.z };
      let targetVel = { x: 0, y: 0, z: 0 };
      let kpX = 6.8, kdX = 4.3, kpZ = 12.0, kdZ = 5.8, kpY = 9.0, kdY = 4.6;
      let useFastZ = false;

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (targetIndex !== obs.gateIndex) {
          targetIndex = obs.gateIndex;
          intX *= 0.2; intZ *= 0.2;
        }

        const dx = gate.x - p.x;
        const dy = Math.abs(p.y - gate.y);
        const dz = Math.abs(p.z - gate.z);

        // Predict Z and Y error 0.12s into the future including fast disturbance acceleration
        const predZ = p.z + v.z * 0.11;
        const predY = p.y + v.y * 0.11;
        const predDz = Math.abs(predZ - gate.z);
        const predDy = Math.abs(predY - gate.y);

        // Gust detection: sudden difference between fastZ and distZ or large predDz
        const gustActive = Math.abs(fastZ - distZ) > 1.8;

        if (dx < 0) {
          // Missed gate: fly back behind it while staying outside the frame in Z or Y if needed
          // Wait, if we are within the frame's Z/Y span and dx < 0, crossing backwards would hit the frame!
          // Actually, crossing backwards through the opening (dy < 0.14 && dz < 0.035) is safe, OR going around (dy > 0.36).
          if (dy < 0.11 && dz < 0.025) {
            target = { x: gate.x - 0.26, y: gate.y, z: gate.z };
          } else {
            // Go over the top of the gate frame (outer + bodyHeight = 0.28 + 0.07 = 0.35 -> y = gate.y + 0.42)
            target = { x: gate.x - 0.30, y: Math.min(2.75, gate.y + 0.42), z: gate.z };
          }
        } else {
          // Approaching gate from p.x < gate.x
          useFastZ = dx < 0.55;
          const zAligned = dz < 0.020 && predDz < 0.022 && Math.abs(v.z) < 0.18 && !gustActive;
          const yAligned = dy < 0.075 && predDy < 0.085 && Math.abs(v.y) < 0.32;

          if (zAligned && yAligned && dx < 0.48) {
            // Cleared to cross! Drive straight through at good speed
            target = { x: gate.x + 0.28, y: gate.y, z: gate.z };
            targetVel = { x: 1.35, y: 0, z: 0 };
            kpZ = 15.5; kdZ = 6.8;
            kpY = 11.5; kdY = 5.2;
          } else if (dx > 0.38) {
            // Far from gate: fly fast towards staging point while aligning Z and Y
            const stageOffset = clamp(0.18 + 1.8 * dz + 0.6 * dy, 0.20, 0.38);
            target = { x: gate.x - stageOffset, y: gate.y, z: gate.z };
            targetVel = { x: clamp(1.4 * (dx - stageOffset), 0, 1.5), y: 0, z: 0 };
          } else {
            // Close to gate (dx <= 0.38) and NOT aligned: hold / brake before gate plane!
            const safeDist = gustActive ? 0.26 : 0.20;
            target = { x: gate.x - safeDist, y: gate.y, z: gate.z };
            targetVel = { x: 0, y: 0, z: 0 };
            if (dx < 0.22 && v.x > 0.05) {
              // Emergency brake in X
              kpX = 11.0; kdX = 6.2;
            }
            kpZ = 15.0; kdZ = 6.5;
            kpY = 11.0; kdY = 5.2;
          }
        }
      } else {
        const pad = obs.pad.centre;
        if (targetIndex !== 3) {
          targetIndex = 3;
          intX *= 0.2; intZ *= 0.2;
        }
        const horizErr = Math.hypot(pad.x - p.x, pad.z - p.z);
        const horizSpd = Math.hypot(v.x, v.z);
        useFastZ = true;

        if (horizErr > 0.13) {
          // Fast diagonal descent toward pad
          const targetY = clamp(0.14 + 0.45 * horizErr, 0.14, 0.85);
          target = { x: pad.x, y: targetY, z: pad.z };
          kpX = 7.5; kdX = 4.6;
          kpZ = 8.5; kdZ = 4.8;
        } else {
          // Inside horizontal radius: descend softly and hold
          target = { x: pad.x, y: 0.05, z: pad.z };
          targetVel = { x: 0, y: p.y > 0.14 ? -0.35 : -0.12, z: 0 };
          kpX = 8.0; kdX = 4.8;
          kpZ = 8.5; kdZ = 4.8;
        }
      }

      const ex = clamp(target.x - p.x, -0.85, 0.85);
      const ey = clamp(target.y - p.y, -0.85, 0.85);
      const ez = clamp(target.z - p.z, -0.85, 0.85);

      if (Math.abs(target.x - p.x) < 0.28) intX = clamp(intX + ex * dt, -0.35, 0.35);
      if (Math.abs(target.y - p.y) < 0.28) intY = clamp(intY + ey * dt, -0.35, 0.35);
      if (Math.abs(target.z - p.z) < 0.25) intZ = clamp(intZ + ez * dt, -0.35, 0.35);

      const effDistZ = useFastZ ? (0.45 * distZ + 0.55 * fastZ) : distZ;
      const effDistY = useFastZ ? (0.6 * distY + 0.4 * fastY) : distY;

      const ax = clamp(kpX * ex + kdX * (targetVel.x - v.x) + 2.5 * intX - distX, -7.0, 7.0);
      const az = clamp(kpZ * ez + kdZ * (targetVel.z - v.z) + 3.8 * intZ - effDistZ, -7.0, 7.0);
      const ay = clamp(kpY * ey + kdY * (targetVel.y - v.y) + 2.5 * intY - effDistY, -5.5, 6.8);

      const totalAy = Math.max(2.0, 9.81 + ay);
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const bodyAx = cy * ax - sy * az;
      const bodyAz = sy * ax + cy * az;

      let maxTilt = obs.t < 0.20 ? 0.38 : 0.56;
      if (obs.gateIndex === 3 && p.y < 0.12 && Math.hypot(obs.pad.centre.x - p.x, obs.pad.centre.z - p.z) < 0.135) {
        maxTilt = 0.15;
      }

      const pitch = clamp(Math.atan2(bodyAx, totalAy), -maxTilt, maxTilt);
      const roll = clamp(-Math.atan2(bodyAz, totalAy), -maxTilt, maxTilt);

      const cosTilt = Math.max(0.55, Math.cos(att.roll) * Math.cos(att.pitch));
      const reqThrustAcc = totalAy / (cosTilt * massScale);

      let thrust = clamp(reqThrustAcc / 20.0, 0, 0.83);
      if (obs.gateIndex === 3 && p.y <= 0.092 && Math.hypot(obs.pad.centre.x - p.x, obs.pad.centre.z - p.z) < 0.125 && Math.abs(v.y) < 0.35) {
        thrust = 0;
      }
      estThrustAcc += 0.25 * (thrust * 20.0 - estThrustAcc);

      return { thrust, roll, pitch, yawRate: clamp(-2.5 * att.yaw, -2, 2) };
    },
  };
}

